#!/usr/bin/env python3
import argparse
import csv
from collections import Counter


def count_nonempty(path):
    counts = Counter()
    with open(path, newline="", encoding="utf-8-sig") as f:
        reader = csv.DictReader(f)
        if not reader.fieldnames:
            raise SystemExit("CSV 文件为空或没有表头")
        for row in reader:
            for col in reader.fieldnames:
                value = (row.get(col) or "").strip()
                if value:
                    counts[col] += 1
    return reader.fieldnames, counts


def main():
    parser = argparse.ArgumentParser(description="统计 CSV 每一列的非空值数量")
    parser.add_argument("csv_file", help="CSV 文件路径")
    args = parser.parse_args()

    fieldnames, counts = count_nonempty(args.csv_file)
    width = max(len(name) for name in fieldnames)
    for name in fieldnames:
        print(f"{name.ljust(width)}  {counts[name]}")


if __name__ == "__main__":
    main()
